
    const app=document.querySelector('#app');
    const paths={home:'/page',login:'/iniciar-sesion',signup:'/loginn',dashboard:'/dashboard-2',analysis:'/nuevo-analisis-2',history:'/historial-2',report:'/informe-2',settings:'/ajustes-2',profile:'/perfil'};
    const navItems=[['dashboard','▦','Panel de control'],['analysis','＋','Nuevo análisis'],['history','◷','Historial'],['report','▤','Informes'],['settings','⚙','Ajustes']];
    let toastTimer;
    function route(){let p=decodeURI(location.hash.slice(1))||paths.home;return Object.keys(paths).find(k=>paths[k]===p)||'home'}
    function go(key){location.hash=paths[key]||paths.home}
    function brand(invert=false){return `<a class="brand ${invert?'brand-invert':''}" href="#${paths.home}"><img class="brand-symbol" src="assets/linksight_simbolo.png" alt=""><span>LinkSight</span></a>`}
    function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),3000)}
    function home(){return `<header class="site-header">${brand()}<nav class="site-nav"><a href="#caracteristicas">Características</a><a href="#como-funciona">Cómo funciona</a><a href="#resultados">Informes</a><a href="#caracteristicas">Seguridad</a></nav><div class="site-actions"><a class="btn btn-quiet" href="#${paths.login}">Iniciar sesión</a><a class="btn btn-primary" href="#${paths.signup}">Crear cuenta</a></div></header>
      <section class="hero"><div><span class="eyebrow">Seguridad web, más clara</span><h1>Encuentra vulnerabilidades <em>antes que los atacantes.</em></h1><p class="hero-copy">Audita tu web de forma sencilla. Detecta riesgos, entiende su impacto y descubre qué corregir primero con informes claros y accionables.</p><div class="hero-buttons"><a class="btn btn-primary" href="#${paths.signup}">Empieza a analizar <span>→</span></a><a class="btn btn-outline" href="#como-funciona">Ver cómo funciona</a></div><div class="trust-row"><span>Análisis bajo demanda</span><span>Informes accionables</span><span>Control total</span></div></div><div class="hero-visual" id="resultados"><div class="preview-top"><span>${brand()}</span><span class="pill pill-green">● Análisis completado</span></div><div style="font:700 12px Manrope;margin:2px 0 10px">Resumen de seguridad <span class="muted" style="font:10px 'DM Sans'">· ejemplo</span></div><div class="preview-metrics"><div class="preview-metric"><b style="color:#d84b55">2</b><span>Críticas</span></div><div class="preview-metric"><b style="color:#e78b27">5</b><span>Altas</span></div><div class="preview-metric"><b style="color:#d9ae38">4</b><span>Medias</span></div><div class="preview-metric"><b style="color:#2e9d69">3</b><span>Bajas</span></div></div><div class="preview-chart"><div style="display:flex;justify-content:space-between;font-size:9px"><b>Hallazgos por severidad</b><span class="muted">14 en total</span></div><div class="bar"><i style="width:78%;background:linear-gradient(90deg,#f1aa48,#e36b35)"></i></div><div class="preview-findings"><div class="finding-line"><span>Cabeceras de seguridad incompletas</span><span class="pill pill-orange">Alta</span></div><div class="finding-line"><span>Dependencia vulnerable detectada</span><span class="pill pill-red">Crítica</span></div><div class="finding-line"><span>Certificado TLS correctamente configurado</span><span class="pill pill-green">Correcto</span></div></div></div></div></section>
      <section class="features" id="caracteristicas"><div class="features-head"><span class="eyebrow">Todo lo que necesitas</span><h2>Seguridad web sin complicaciones</h2><p class="page-subtitle">De la primera revisión a la corrección, con toda la información en un solo lugar.</p></div><div class="feature-grid"><article class="card feature"><div class="feature-icon">⌕</div><h3>Análisis completo</h3><p>Revisa tu web y sus componentes para encontrar riesgos de seguridad.</p></article><article class="card feature"><div class="feature-icon">◉</div><h3>Prioridades claras</h3><p>Entiende la gravedad de cada hallazgo y decide por dónde empezar.</p></article><article class="card feature"><div class="feature-icon">▤</div><h3>Informes accionables</h3><p>Consulta evidencias y recomendaciones para resolver los problemas.</p></article><article class="card feature"><div class="feature-icon">⌁</div><h3>Historial de análisis</h3><p>Compara resultados y sigue la evolución de la seguridad de tu web.</p></article></div><div id="como-funciona" class="features-head" style="margin-top:45px"><span class="eyebrow">En tres pasos</span><h2>Conoce el estado de tu web</h2><p class="page-subtitle">Crea tu cuenta, lanza un análisis y revisa los resultados desde tu panel.</p><a class="btn btn-primary" style="margin-top:15px" href="#${paths.signup}">Crear cuenta gratis →</a></div></section><footer class="site-footer">${brand()}<span>© 2025 LinkSight · Seguridad web más comprensible · <b>Versión 2026.10.30-2</b></span></footer>`}
    function auth(signup){return `<div class="auth-page"><aside class="auth-aside">${brand(true)}<div class="auth-message"><h1>Audita la seguridad de tu web con nosotros.</h1><p>Detecta vulnerabilidades, entiende su impacto y prioriza las mejoras que debes aplicar.</p><div class="auth-benefits"><span>Análisis estáticos y dinámicos</span><span>Informes claros y accionables</span><span>Seguimiento de vulnerabilidades</span><span>Gestión de dependencias</span></div></div><div class="auth-foot">© 2025 LinkSight · Seguridad web más comprensible · <b>Versión 2026.10.30-2</b></div></aside><a class="auth-back" href="#${paths.home}">← Volver al inicio</a><section class="auth-main"><form class="auth-box" data-form="${signup?'signup':'login'}"><h2>${signup?'Crear cuenta':'Iniciar sesión'}</h2><p>${signup?'Empieza a proteger tus proyectos.':'Accede a tu panel de seguridad.'}</p>${signup?`<div class="field"><label for="name">Nombre completo</label><input id="name" name="name" placeholder="Tu nombre" required></div>`:''}<div class="field"><label for="email">Correo electrónico</label><input id="email" type="email" name="email" placeholder="nombre@empresa.com" required></div><div class="field"><label for="password">Contraseña</label><input id="password" type="password" name="password" placeholder="${signup?'Mínimo 8 caracteres':'Tu contraseña'}" minlength="8" required></div>${signup?`<div class="field"><label for="confirm">Confirmar contraseña</label><input id="confirm" type="password" name="confirm" placeholder="Repite tu contraseña" minlength="8" required></div><label class="checkline"><input type="checkbox" required><span>He leído y acepto las <a class="text-link" href="#">condiciones de uso</a> y la política de privacidad.</span></label>`:`<div class="auth-meta"><label class="checkline"><input type="checkbox"><span>Recordarme</span></label><a class="text-link" href="#" data-action="forgot">¿Has olvidado tu contraseña?</a></div>`}<button class="btn btn-primary auth-submit" type="submit">${signup?'Crear cuenta':'Iniciar sesión'}</button><div class="auth-switch">${signup?'¿Ya tienes cuenta?':'¿Todavía no tienes cuenta?'} <a href="#${signup?paths.login:paths.signup}">${signup?'Inicia sesión':'Regístrate'}</a></div></form></section></div>`}
    function navLink(item,current){return `<a class="nav-link ${item[0]===current?'active':''}" href="#${paths[item[0]]}"><span class="nav-icon">${item[1]}</span>${item[2]}</a>`}
    function shell(current,body){return `<div class="app-shell"><header class="topbar"><div class="top-left"><button class="icon-btn mobile-menu" aria-label="Abrir menú" data-action="menu">☰</button>${brand()}<span class="top-divider"></span><span class="top-crumb">${navItems.find(x=>x[0]===current)?.[2]||'Mi perfil'}</span></div><div class="top-right"><button class="icon-btn" title="Notificaciones" data-action="notifications">♧</button><div class="profile-wrap"><button class="avatar" data-action="profile-menu">A</button><div class="profile-menu hidden" id="profile-menu"><a href="#${paths.profile}">Mi perfil</a><a href="#${paths.settings}">Ajustes</a><a href="#${paths.dashboard}">Panel de control</a><button class="logout" data-action="logout">Cerrar sesión</button></div></div></div></header><aside class="sidebar" id="sidebar"><div class="side-label">Menú principal</div>${navItems.map(i=>navLink(i,current)).join('')}<div class="side-bottom"><div class="side-label">Cuenta</div>${navLink(['profile','◉','Mi perfil'],current)}<div class="support-card"><b>¿Necesitas ayuda?</b><p>Consulta nuestra guía o contacta con soporte.</p><a href="#" data-action="help">Centro de ayuda →</a></div></div></aside><section class="workspace"><div class="content">${body}</div></section></div>`}
    const scans=[['LS-2025-084','tienda-ejemplo.es','Completo','28 oct 2025','14','Alta','Completado'],['LS-2025-083','api.empresa.com','Dinámico','26 oct 2025','8','Media','Completado'],['LS-2025-082','portal.demo.es','Estático','24 oct 2025','3','Baja','Completado'],['LS-2025-081','tienda-ejemplo.es','Completo','21 oct 2025','17','Crítica','Completado'],['LS-2025-080','app.ejemplo.net','Dinámico','18 oct 2025','6','Media','Completado']];
    function severityPill(s){return `<span class="pill ${s==='Crítica'?'pill-red':s==='Alta'?'pill-orange':s==='Media'?'pill-orange':'pill-green'}">${s}</span>`}
    function scanTable(rows=scans){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>ID</th><th>Sitio web</th><th>Tipo</th><th>Fecha</th><th>Hallazgos</th><th>Severidad máx.</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${r[0]}</td><td class="url-cell">${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${severityPill(r[5])}</td><td><span class="pill pill-green">● ${r[6]}</span></td><td><a class="text-link" href="#${paths.report}" data-report="${i}">Ver informe</a></td></tr>`).join('')}</tbody></table></div>`}
   function dashboard(){return shell('dashboard',`<div class="content-header"><div><h1 class="page-title">Panel de control</h1><p class="page-subtitle">Resumen del estado de seguridad de tus proyectos.</p></div><div class="header-actions"><a class="btn btn-primary" href="#${paths.analysis}">＋ Nuevo análisis</a></div></div><div class="stats-grid"><article class="card stat-card"><div class="stat-top"><span>Análisis realizados</span><span class="stat-icon">⌕</span></div><div class="stat-value">0</div><div class="stat-note">Total de análisis</div></article><article class="card stat-card"><div class="stat-top"><span>Vulnerabilidades críticas</span><span class="stat-icon" style="color:var(--red);background:#fff0f0">!</span></div><div class="stat-value">0</div><div class="stat-note">En los análisis visibles</div></article><article class="card stat-card"><div class="stat-top"><span>Dependencias vulnerables</span><span class="stat-icon" style="color:var(--orange);background:#fff5e8">⌘</span></div><div class="stat-value">0</div><div class="stat-note">Registradas en análisis</div></article></div><div class="dash-grid"><article class="card card-pad" id="dashboard-severity"><div class="card-heading"><div><h3>Hallazgos por severidad</h3><p>Vulnerabilidades detectadas en tus análisis</p></div></div><div class="severity-list"><div class="severity-row"><span>Crítica</span><div class="bar"><i style="width:0%;background:#d94f58"></i></div><b>0</b></div><div class="severity-row"><span>Alta</span><div class="bar"><i style="width:0%;background:#ef902d"></i></div><b>0</b></div><div class="severity-row"><span>Media</span><div class="bar"><i style="width:0%;background:#e5b344"></i></div><b>0</b></div><div class="severity-row"><span>Baja</span><div class="bar"><i style="width:0%;background:#36a575"></i></div><b>0</b></div></div></article><article class="card card-pad" id="dashboard-types"><div class="card-heading"><div><h3>Tipos de vulnerabilidad</h3><p>Distribución de hallazgos</p></div></div><div class="severity-list"><p class="muted tiny">Aún no hay hallazgos registrados.</p></div></article></div><div class="dash-grid"><article class="card card-pad" id="dashboard-recent"><div class="card-heading"><div><h3>Últimos análisis</h3><p>Actividad reciente en tus proyectos</p></div><a class="text-link tiny" href="#${paths.history}">Ver historial →</a></div><p class="muted tiny">Todavía no hay análisis</p></article></div>`)}
    function analysis(){return shell('analysis',`<div class="content-header"><div><h1 class="page-title">Nuevo análisis</h1><p class="page-subtitle">Configura la auditoría de seguridad de tu sitio web.</p></div><a class="btn btn-outline" href="#${paths.history}">Ver historial</a></div><form id="analysis-form"><div class="analysis-grid"><div><section class="card form-section"><h3>Objetivo del análisis</h3><p>Indica qué web quieres revisar y cómo quieres analizarla.</p><div class="form-grid"><div class="field full"><label for="url">URL del sitio web</label><input id="url" type="url" placeholder="https://www.ejemplo.com" required></div><div class="field"><label for="scan-type">Tipo de análisis</label><select id="scan-type"><option>Completo</option><option>Estático</option><option>Dinámico</option></select></div><div class="field"><label for="scan-name">Nombre del análisis</label><input id="scan-name" placeholder="Ej. Auditoría octubre"></div></div></section><section class="card form-section"><h3>Módulos de seguridad</h3><p>Selecciona las comprobaciones que quieres incluir.</p><div class="module-grid"><label class="module"><input type="checkbox" checked><span><b>Análisis estático</b><small>Revisión del código y configuración</small></span></label><label class="module"><input type="checkbox" checked><span><b>Análisis dinámico</b><small>Pruebas sobre la aplicación activa</small></span></label><label class="module"><input type="checkbox" checked><span><b>Dependencias</b><small>Detección de paquetes vulnerables</small></span></label><label class="module"><input type="checkbox"><span><b>Cabeceras y SSL</b><small>Configuración del servidor y TLS</small></span></label></div><div class="field"><label for="source">Código fuente (opcional)</label><input id="source" type="text" placeholder="URL del repositorio o ruta del proyecto"><small class="muted tiny">Añade un repositorio para incluir el análisis de código.</small></div></section><section class="card form-section"><h3>Validación con IA</h3><p>Usa una revisión adicional para reducir falsos positivos y priorizar correcciones.</p><label class="checkline"><input type="checkbox" checked><span>Activar validación inteligente de hallazgos</span></label><div class="notice">La validación añade contexto y recomendaciones a los resultados. El análisis puede tardar unos minutos.</div></section><section class="card form-section"><label class="checkline"><input type="checkbox" required><span>Confirmo que tengo autorización para analizar este sitio web.</span></label></section></div><aside class="card summary-card"><h3>Resumen del análisis</h3><div class="summary-row"><span>Objetivo</span><b id="summary-url">Pendiente</b></div><div class="summary-row"><span>Tipo</span><b id="summary-type">Completo</b></div><div class="summary-row"><span>Módulos</span><b id="summary-modules">3 seleccionados</b></div><div class="summary-total">El análisis revisará el objetivo indicado y mostrará los hallazgos en tu historial.</div><button class="btn btn-primary" type="submit">Iniciar análisis →</button><button class="btn btn-quiet" type="button" style="width:100%" data-action="save-draft">Guardar como borrador</button></aside></div></form>`)}
    function history(){return shell('history',`<div class="content-header"><div><h1 class="page-title">Historial de análisis</h1><p class="page-subtitle">Consulta y compara los análisis realizados en tus proyectos.</p></div><a class="btn btn-primary" href="#${paths.analysis}">＋ Nuevo análisis</a></div><section class="card history-card"><div class="history-toolbar"><div class="toolbar"><label class="searchbox"><input id="history-search" placeholder="Buscar por web o ID..."></label><select class="filter-select" id="type-filter"><option value="">Todos los tipos</option><option>Completo</option><option>Estático</option><option>Dinámico</option></select><select class="filter-select" id="severity-filter"><option value="">Cualquier severidad</option><option>Crítica</option><option>Alta</option><option>Media</option><option>Baja</option></select></div><button class="btn btn-outline btn-small" data-action="export">↓ Exportar CSV</button></div><div id="history-table">${scanTable()}</div><div class="pagination"><button>‹</button><button class="selected">1</button><button>2</button><button>3</button><button>›</button></div></section>`)}
   function report(){return shell('report',`<div class="content-header"><div><h1 class="page-title">Informes</h1><p class="page-subtitle">Informes generados a partir de análisis y hallazgos guardados.</p></div><div class="toolbar"><button class="btn btn-outline btn-small" data-action="markdown">↓ Markdown</button><button class="btn btn-primary btn-small" data-action="pdf">↓ Imprimir / PDF</button></div></div><div class="reports-layout"><section class="card report-list"><div class="card-heading"><div><h3>Informes guardados</h3><p>Cargando informes…</p></div></div></section><section class="card report-detail"><p class="muted">Los informes se cargarán desde MariaDB.</p></section></div>`)}
    function settings(){return shell('settings',`<div class="content-header"><div><h1 class="page-title">Ajustes</h1><p class="page-subtitle">Gestiona tu perfil, integraciones y preferencias de seguridad.</p></div><button class="btn btn-primary" data-action="save-settings">Guardar cambios</button></div><div class="settings-grid"><section class="card setting-card"><h3>Perfil</h3><p>Información básica de tu cuenta.</p><div class="form-grid"><div class="field"><label>Nombre</label><input value="Aleix"></div><div class="field"><label>Apellidos</label><input value="Usuario"></div><div class="field full"><label>Correo electrónico</label><input type="email" value="aleix@ejemplo.com"></div><div class="field full"><label>Zona horaria</label><select><option>Europe/Madrid (UTC+1)</option><option>UTC</option></select></div></div></section><section class="card setting-card"><h3>Conexión con el bastión</h3><p>Configura la conexión segura con tu infraestructura.</p><div class="setting-row"><span>Estado de conexión<small>Última comprobación hace 2 min</small></span><span class="pill pill-green">Conectado</span></div><div class="field"><label>Dirección del bastión</label><input value="bastion.linksight.local"></div><div class="field"><label>Puerto</label><input value="22"></div><button class="btn btn-outline btn-small" data-action="check-connection">Probar conexión</button></section><section class="card setting-card"><h3>Integraciones disponibles</h3><p>Conecta las herramientas de tu equipo.</p>${['GitHub','GitLab','Jira'].map((n,i)=>`<div class="setting-row"><span>${n}<small>${i===0?'Repositorio de código':'Gestión de proyectos'}</small></span><button class="btn btn-outline btn-small" data-action="integration">${i===0?'Conectado':'Conectar'}</button></div>`).join('')}</section><section class="card setting-card"><h3>Informes y notificaciones</h3><p>Personaliza cómo recibes los resultados.</p>${[['Informe en PDF','Incluir resumen ejecutivo'],['Notificaciones por correo','Al finalizar un análisis'],['Alertas críticas','Avisar si se detecta un riesgo crítico']].map((x,i)=>`<div class="setting-row"><span>${x[0]}<small>${x[1]}</small></span><input class="toggle" type="checkbox" ${i!==1?'checked':''}></div>`).join('')}</section><section class="card setting-card"><h3>Seguridad de la cuenta</h3><p>Protege el acceso a tu cuenta de LinkSight.</p><div class="setting-row"><span>Verificación en dos pasos<small>Añade una capa extra de seguridad</small></span><input class="toggle" type="checkbox"></div><div class="field"><label>Sesiones abiertas</label><div class="list-item"><span>Este dispositivo · Madrid, España</span><span class="pill pill-green">Activa</span></div></div><button class="btn btn-outline btn-small" data-action="password">Cambiar contraseña</button></section></div>`)}
   function profile(){return shell('profile',`<div class="content-header"><div><h1 class="page-title">Mi perfil</h1><p class="page-subtitle">Consulta tus datos personales y la actividad de tu cuenta.</p></div></div><div class="profile-grid"><section class="card profile-card"><img class="profile-big" id="profile-photo" src="/assets/avatar-default.svg" alt="Foto de perfil" style="object-fit:cover"><h2>Cargando perfil…</h2><p></p><div class="profile-facts"><div class="profile-fact"><span>Miembro desde</span><b>—</b></div><div class="profile-fact"><span>Análisis realizados</span><b>—</b></div><div class="profile-fact"><span>Proyectos</span><b>—</b></div><div class="profile-fact"><span>Último acceso</span><b>—</b></div></div><button class="btn btn-danger btn-small" style="margin-top:14px" data-action="logout">Cerrar sesión</button></section><div class="profile-panels"><section class="card setting-card"><h3>Información personal</h3><p>Datos asociados a tu cuenta.</p><div class="form-grid"><div class="field"><label>Nombre</label><input readonly></div><div class="field"><label>Apellidos</label><input readonly></div><div class="field"><label>Correo electrónico</label><input readonly></div><div class="field"><label>Rol</label><input readonly></div></div></section><section class="card setting-card"><h3>Seguridad</h3><p>Sesiones activas de la cuenta.</p><div class="setting-row"><span>Cargando sesiones…<small></small></span></div></section></div></div>`)}
    function render(){const key=route();document.title=`${key==='home'?'Seguridad web':({login:'Iniciar sesión',signup:'Crear cuenta',dashboard:'Panel de control',analysis:'Nuevo análisis',history:'Historial',report:'Informes',settings:'Ajustes',profile:'Mi perfil'}[key]||'LinkSight')} · LinkSight`;app.innerHTML=key==='home'?home():key==='login'?auth(false):key==='signup'?auth(true):key==='dashboard'?dashboard():key==='analysis'?analysis():key==='history'?history():key==='report'?report():key==='settings'?settings():profile();window.scrollTo(0,0)}
    app.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='analysis-form'){const url=document.querySelector('#url').value;notify(`Análisis de ${url} añadido a la cola.`);setTimeout(()=>go('history'),900)}else if(form.dataset.form==='signup'){const d=new FormData(form);if(d.get('password')!==d.get('confirm')){notify('Las contraseñas no coinciden.');return}notify('Cuenta creada. Ya puedes iniciar sesión.');setTimeout(()=>go('login'),900)}else if(form.dataset.form==='login'){notify('Sesión iniciada. Bienvenido a LinkSight.');setTimeout(()=>go('dashboard'),700)}});
    app.addEventListener('input',e=>{if(e.target.id==='url')document.querySelector('#summary-url').textContent=e.target.value||'Pendiente';if(e.target.id==='scan-type')document.querySelector('#summary-type').textContent=e.target.value;if(e.target.matches('.module input'))document.querySelector('#summary-modules').textContent=`${document.querySelectorAll('.module input:checked').length} seleccionados`;if(e.target.id?.startsWith('history-')||e.target.id==='type-filter'||e.target.id==='severity-filter')filterHistory()});
    app.addEventListener('change',e=>{if(e.target.id==='scan-type')document.querySelector('#summary-type').textContent=e.target.value;if(e.target.matches('.module input'))document.querySelector('#summary-modules').textContent=`${document.querySelectorAll('.module input:checked').length} seleccionados`;if(['history-search','type-filter','severity-filter'].includes(e.target.id))filterHistory()});
    function filterHistory(){const q=(document.querySelector('#history-search')?.value||'').toLowerCase(),t=document.querySelector('#type-filter')?.value||'',s=document.querySelector('#severity-filter')?.value||'';const rows=scans.filter(r=>(!q||r[0].toLowerCase().includes(q)||r[1].toLowerCase().includes(q))&&(!t||r[2]===t)&&(!s||r[5]===s));const el=document.querySelector('#history-table');if(el)el.innerHTML=rows.length?scanTable(rows):'<p class="muted tiny" style="padding:20px">No hay análisis que coincidan con los filtros.</p>'}
