    document.querySelectorAll('.stat-value').forEach((el,i)=>{if(i<3)el.textContent=Number(stats[i]||0)});
    const severityMap=Object.fromEntries(data.severity.map(x=>[x.severidad,Number(x.total)]));
    const severityMax=Math.max(0,...Object.values(severityMap));
    const severityRows=document.querySelectorAll('#dashboard-severity .severity-row');
    ['critica','alta','media','baja'].forEach((key,i)=>{const row=severityRows[i];if(!row)return;const n=severityMap[key]||0;row.querySelector('b').textContent=n;row.querySelector('.bar i').style.width=`${severityMax?Math.round(n/severityMax*100):0}%`});
    const typesCard=document.querySelector('#dashboard-types');
    if(typesCard){const list=typesCard.querySelector('.severity-list');const max=Math.max(0,...data.types.map(x=>Number(x.total)));list.innerHTML=data.types.length?data.types.map(x=>`<div class="severity-row"><span>${h(x.nombre)}</span><div class="bar"><i style="width:${max?Math.round(Number(x.total)/max*100):0}%"></i></div><b>${Number(x.total)}</b></div>`).join(''):'<p class="muted tiny">Aún no hay hallazgos registrados.</p>'}
