    const visible=liveScans.filter(r=>(!q||`${r.codigo} ${r.objetivo}`.toLocaleLowerCase('es').includes(q))&&(!type||typeLabel(r.tipo)===type)&&(!severity||severityLabel(r.severidad_max)===severity));
